#include "gtest/gtest.h"
#include "parser/parser.h"
#include "CRC/checksum.h"

/**
 * ===============================================================
 * FIRST : CRC calculations
 * ===============================================================
 */
// The library match agains this :
// https://emn178.github.io/online-tools/crc/


TEST(CRC, CRCCalc1)
{
	const unsigned char buf = 'A';

	uint32_t retval = crc_32(&buf, 1);

	ASSERT_EQ(retval, 0xd3d99e8b);
}

TEST(CRC, CRCCalc2)
{
	const unsigned char *buf = (const unsigned char*)"AAAAAAAA";

	uint32_t retval = crc_32(buf, 8);

	ASSERT_EQ(retval, 0x79b71c0a);
}

TEST(CRC, CRCCalc3)
{
	const unsigned char *buf = (const unsigned char*)"";

	uint32_t retval = crc_32(buf, 500);

	ASSERT_EQ(retval, 0xd881338f);
}

TEST(CRC, CRCCalc4)
{
	const unsigned char *buf = (const unsigned char*)"";

	uint32_t retval = crc_32(buf, 995);

	ASSERT_EQ(retval, 0x483edd57);
}

/*
 * Real word usages are done under the PARSER test, which use it exclusively.
 */

